head.b:skin:
:root{
  --pr:#2563eb;--pr2:#1d4ed8;--pr-light:#eff6ff;--pr-border:#bfdbfe;
  --green:#059669;--green-light:#ecfdf5;
  --amber:#d97706;--amber-light:#fffbeb;
  --red:#dc2626;--red-light:#fef2f2;
  --bg:#f8fafc;--surface:#fff;
  --bord:#e2e8f0;--bord2:#cbd5e1;
  --txt:#0f172a;--txt2:#475569;--txt3:#94a3b8;
  --r:14px;--r2:10px;--r3:8px;
  --shadow:0 1px 3px rgba(0,0,0,.08),0 1px 2px rgba(0,0,0,.06);
  --shadow-md:0 4px 6px -1px rgba(0,0,0,.08),0 2px 4px -1px rgba(0,0,0,.05);
  --shadow-lg:0 10px 15px -3px rgba(0,0,0,.08),0 4px 6px -2px rgba(0,0,0,.04);
  --shadow-xl:0 20px 25px -5px rgba(0,0,0,.1),0 10px 10px -5px rgba(0,0,0,.04);
}
*{box-sizing:border-box;margin:0;padding:0;}
body{font-family:'Tajawal',sans-serif;background:var(--bg);color:var(--txt);min-height:100vh;direction:rtl;-webkit-font-smoothing:antialiased;}

/* ── LOGIN ── */
#login-screen{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;background:linear-gradient(135deg,#1e3a8a 0%,#1d4ed8 40%,#2563eb 70%,#3b82f6 100%);}
#login-screen::before{content:'';position:fixed;inset:0;background:url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");pointer-events:none;}
.login-card{width:100%;max-width:420px;background:rgba(255,255,255,.97);border-radius:24px;padding:40px 36px;box-shadow:0 25px 50px rgba(0,0,0,.3);position:relative;z-index:1;}
.login-logo{text-align:center;margin-bottom:28px;}
.login-logo .icon-wrap{width:72px;height:72px;background:linear-gradient(135deg,#2563eb,#1d4ed8);border-radius:20px;display:inline-flex;align-items:center;justify-content:center;font-size:36px;margin-bottom:14px;box-shadow:0 8px 20px rgba(37,99,235,.4);}
.login-logo h1{font-size:22px;font-weight:800;color:var(--txt);margin-bottom:4px;}
.login-logo p{font-size:13.5px;color:var(--txt2);}
.login-field{margin-bottom:18px;}
.login-field label{display:block;font-size:13px;font-weight:700;color:var(--txt2);margin-bottom:7px;}
.login-field input{width:100%;padding:13px 16px;border:1.5px solid var(--bord);border-radius:var(--r3);font-size:15px;font-family:inherit;color:var(--txt);outline:none;transition:border-color .2s,box-shadow .2s;background:#fff;}
.login-field input:focus{border-color:var(--pr);box-shadow:0 0 0 3px rgba(37,99,235,.1);}
.login-btn{width:100%;padding:14px;background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;border:none;border-radius:var(--r3);font-size:15px;font-weight:800;font-family:inherit;cursor:pointer;transition:.2s;box-shadow:0 4px 14px rgba(37,99,235,.4);margin-top:4px;}
.login-btn:hover{transform:translateY(-1px);box-shadow:0 6px 20px rgba(37,99,235,.5);}
.login-btn:disabled{background:#94a3b8;box-shadow:none;cursor:not-allowed;transform:none;}
.login-err{color:var(--red);font-size:13px;font-weight:600;text-align:center;margin-top:12px;min-height:18px;}

/* ── HEADER ── */
.hdr{background:linear-gradient(135deg,#1e3a8a,#2563eb);color:#fff;padding:0 20px;height:60px;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:100;box-shadow:0 2px 16px rgba(37,99,235,.35);}
.hdr-brand{display:flex;align-items:center;gap:10px;}
.hdr-brand .logo{width:36px;height:36px;background:rgba(255,255,255,.2);border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:20px;}
.hdr-brand h1{font-size:17px;font-weight:800;}
.hdr-brand p{font-size:11px;opacity:.8;margin-top:1px;}
.hdr-right{display:flex;align-items:center;gap:8px;}
.user-chip{background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);border-radius:30px;padding:5px 14px;font-size:12.5px;font-weight:700;}
.hdr-logout{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);color:#fff;border-radius:8px;padding:6px 14px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:inherit;transition:.15s;}
.hdr-logout:hover{background:rgba(255,255,255,.22);}

/* ── LAYOUT ── */
.main{max-width:820px;margin:0 auto;padding:24px 16px 100px;}
.hidden{display:none!important;}

/* ── CARDS ── */
.card{background:var(--surface);border-radius:var(--r);border:1px solid var(--bord);padding:22px 24px;margin-bottom:16px;box-shadow:var(--shadow);}
.card-hd{display:flex;align-items:center;gap:10px;margin-bottom:18px;}
.card-hd .card-icon{width:36px;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;}
.card-hd h2{font-size:15px;font-weight:800;color:var(--txt);}
.card-hd p{font-size:12px;color:var(--txt2);margin-top:1px;}

/* ── FIELDS ── */
.field{margin-bottom:16px;}
.field label{display:block;font-size:12px;font-weight:700;color:var(--txt2);margin-bottom:6px;letter-spacing:.3px;}
.field input,.field textarea,.field select{width:100%;padding:11px 14px;border:1.5px solid var(--bord);border-radius:var(--r3);font-size:14px;font-family:inherit;color:var(--txt);background:#fff;outline:none;transition:border-color .2s,box-shadow .2s;}
.field input:focus,.field textarea:focus{border-color:var(--pr);box-shadow:0 0 0 3px rgba(37,99,235,.08);}
.field textarea{resize:vertical;min-height:85px;line-height:1.6;}
.field input[readonly]{background:#f8fafc;color:var(--txt2);cursor:default;}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px;}
.badge-req{background:linear-gradient(135deg,#dbeafe,#bfdbfe);color:#1d4ed8;font-size:10px;font-weight:800;padding:2px 8px;border-radius:20px;}
.badge-opt{background:#f1f5f9;color:var(--txt3);font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px;}
.field-hint{font-size:11px;color:var(--txt3);margin-top:5px;line-height:1.5;}

/* ── VARIANT CARD ── */
.vc-wrap{border:1.5px solid var(--bord);border-radius:var(--r);padding:20px;margin-bottom:14px;background:#fafbfc;transition:border-color .2s;}
.vc-wrap:first-child{border-color:var(--pr-border);background:var(--pr-light);}
.vc-wrap:hover{border-color:var(--bord2);}
.vc-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;}
.vc-title{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:800;color:var(--pr);}
.vc-title .num{width:26px;height:26px;background:var(--pr);color:#fff;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;}
.vc-actions{display:flex;gap:6px;align-items:center;}

/* ── SIZE ROWS ── */
.sr{display:grid;grid-template-columns:1fr 120px 34px;gap:8px;align-items:center;margin-bottom:8px;}
.sr input{padding:9px 12px;border:1.5px solid var(--bord);border-radius:var(--r3);font-size:13px;font-family:inherit;color:var(--txt);outline:none;transition:border-color .2s;}
.sr input:focus{border-color:var(--pr);}

/* ── IMAGE ZONE ── */
.img-zone{border:2px dashed var(--bord2);border-radius:var(--r2);background:#fff;transition:.2s;overflow:hidden;}
.img-zone.drag-over{border-color:var(--pr);background:var(--pr-light);}
.img-zone-body{padding:16px;}
.img-thumbs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;}
.img-thumb{position:relative;width:76px;height:76px;border-radius:10px;overflow:hidden;border:1.5px solid var(--bord);flex-shrink:0;}
.img-thumb img{width:100%;height:100%;object-fit:cover;display:block;}
.img-thumb .rm{position:absolute;top:3px;right:3px;width:20px;height:20px;background:rgba(220,38,38,.9);color:#fff;border:none;border-radius:50%;cursor:pointer;font-size:11px;display:flex;align-items:center;justify-content:center;font-weight:900;}
.img-thumb .overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:#fff;border-radius:10px;}
.img-drop-hint{display:flex;flex-direction:column;align-items:center;gap:6px;padding:16px 8px;color:var(--txt3);cursor:pointer;transition:.2s;}
.img-drop-hint:hover{color:var(--pr);}
.img-drop-hint svg{opacity:.5;}
.img-drop-hint span{font-size:12.5px;font-weight:600;}
.img-url-bar{display:flex;gap:8px;padding:10px 16px;border-top:1px solid var(--bord);background:#f8fafc;}
.img-url-bar input{flex:1;padding:8px 12px;border:1.5px solid var(--bord);border-radius:var(--r3);font-size:13px;font-family:inherit;outline:none;transition:border-color .2s;}
.img-url-bar input:focus{border-color:var(--pr);}

/* ── BUTTONS ── */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:9px 16px;border-radius:var(--r3);font-size:13.5px;font-weight:700;font-family:inherit;cursor:pointer;border:none;transition:.15s;white-space:nowrap;}
.btn-primary{background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;box-shadow:0 2px 8px rgba(37,99,235,.3);}
.btn-primary:hover{box-shadow:0 4px 14px rgba(37,99,235,.4);transform:translateY(-1px);}
.btn-ghost{background:transparent;color:var(--txt2);border:1.5px solid var(--bord);}
.btn-ghost:hover{border-color:var(--pr);color:var(--pr);background:var(--pr-light);}
.btn-danger{background:transparent;color:var(--red);border:1.5px solid #fca5a5;padding:6px 10px;font-size:12px;}
.btn-danger:hover{background:var(--red-light);}
.btn-icon{padding:6px 10px;font-size:13px;}
.btn-add-v{width:100%;padding:14px;border:2px dashed var(--bord2);border-radius:var(--r);background:transparent;color:var(--txt2);font-size:14px;font-weight:700;font-family:inherit;cursor:pointer;transition:.2s;margin-bottom:16px;}
.btn-add-v:hover{border-color:var(--pr);color:var(--pr);background:var(--pr-light);}
.btn-publish{width:100%;padding:16px;background:linear-gradient(135deg,#059669,#047857);color:#fff;border:none;border-radius:var(--r2);font-size:16px;font-weight:900;font-family:inherit;cursor:pointer;box-shadow:0 4px 14px rgba(5,150,105,.35);transition:.2s;}
.btn-publish:hover{box-shadow:0 6px 20px rgba(5,150,105,.45);transform:translateY(-1px);}
.btn-publish:disabled{background:#94a3b8;box-shadow:none;cursor:not-allowed;transform:none;}
.btn-gen{width:100%;padding:14px;background:var(--surface);color:var(--pr);border:2px solid var(--pr);border-radius:var(--r2);font-size:15px;font-weight:800;font-family:inherit;cursor:pointer;transition:.2s;margin-bottom:10px;}
.btn-gen:hover{background:var(--pr-light);}

/* ── SECTION DIVIDER ── */
.sec-div{display:flex;align-items:center;gap:12px;margin:20px 0;}
.sec-div hr{flex:1;border:none;border-top:1.5px dashed var(--bord);}
.sec-div span{font-size:12px;color:var(--txt3);font-weight:600;white-space:nowrap;}

/* ── SETTINGS BAR ── */
.settings-bar{display:flex;gap:10px;margin-bottom:8px;}
.settings-note{font-size:11.5px;color:var(--txt3);text-align:center;line-height:1.6;margin-bottom:16px;}

/* ── IMGBB PANEL ── */
.imgbb-panel{background:linear-gradient(135deg,var(--pr-light),#e0f2fe);border:1.5px solid var(--pr-border);border-radius:var(--r);padding:18px 20px;margin-bottom:16px;}
.imgbb-toggle{display:flex;justify-content:space-between;align-items:center;cursor:pointer;user-select:none;}
.imgbb-toggle-left{display:flex;align-items:center;gap:10px;}
.imgbb-badge{font-size:11px;font-weight:800;padding:3px 10px;border-radius:20px;}
.imgbb-body{margin-top:14px;}
.imgbb-body input{width:100%;padding:11px 14px;border:1.5px solid var(--pr-border);border-radius:var(--r3);font-size:14px;font-family:inherit;outline:none;background:#fff;transition:border-color .2s;}
.imgbb-body input:focus{border-color:var(--pr);}
.imgbb-tip{font-size:11.5px;color:var(--amber);background:var(--amber-light);border:1px solid #fcd34d;border-radius:var(--r3);padding:10px 12px;margin-top:10px;line-height:1.7;}

/* ── OUTPUT ── */
#out-wrap{margin-top:16px;}
.out-card{background:#0f172a;border-radius:var(--r);padding:20px;border:1px solid #1e293b;}
.out-card-hd{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;}
.out-card-hd span{color:#94a3b8;font-size:13px;font-weight:700;}
#out{width:100%;min-height:140px;font-family:'Courier New',monospace;font-size:12px;background:transparent;color:#e2e8f0;border:none;outline:none;resize:vertical;direction:ltr;line-height:1.6;}
.out-steps{background:var(--red-light);border:1.5px solid #f87171;border-radius:var(--r2);padding:14px 16px;margin-top:14px;}
.out-steps-title{font-size:13px;font-weight:800;color:var(--red);margin-bottom:10px;}
.steps{display:flex;flex-direction:column;gap:8px;}
.step{display:flex;gap:10px;align-items:flex-start;font-size:13px;}
.step-n{width:22px;height:22px;min-width:22px;background:var(--pr);color:#fff;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;}
.step-n.red{background:var(--red);}

/* ── STATUS ── */
.pub-status{margin-top:12px;}
.status-box{border-radius:var(--r2);padding:14px 18px;font-size:14px;font-weight:700;text-align:center;}
.status-success{background:var(--green-light);color:var(--green);border:1.5px solid #6ee7b7;}
.status-error{background:var(--red-light);color:var(--red);border:1.5px solid #f87171;}
.status-loading{background:#f0f9ff;color:#0369a1;border:1.5px solid #bae6fd;}

/* ── WARN BANNER ── */
.warn-uploading{background:var(--amber-light);border:1.5px solid #fcd34d;border-radius:var(--r3);padding:10px 14px;font-size:13px;color:var(--amber);font-weight:700;margin-top:12px;}
.warn-base64{background:var(--red-light);border:1.5px solid #f87171;border-radius:var(--r3);padding:10px 14px;font-size:13px;color:var(--red);font-weight:700;margin-top:12px;}

/* ── TOAST ── */
#_toast{position:fixed;bottom:28px;left:50%;transform:translateX(-50%);color:#fff;font-weight:700;font-size:14px;padding:12px 24px;border-radius:40px;box-shadow:0 8px 24px rgba(0,0,0,.25);z-index:9999;opacity:0;transition:opacity .25s;pointer-events:none;max-width:90vw;text-align:center;white-space:nowrap;}

@media(max-width:600px){.grid2{grid-template-columns:1fr;} .hdr-brand p{display:none;} .login-card{padding:28px 20px;} .sr{grid-template-columns:1fr 100px 34px;}}

b:includable.script:
//

var APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbys4Xysb4sOxm7i8PVj3cHRhLe2iHdgWrgKzQULQnyWPtgH65ZExSdKxs2tE11ser2uIg/exec";
var PAGE_FEED_URL   = "/feeds/pages/default/280206546608680039?alt=json";

var currentUser = null;
var vcCount = 0;
var varImgs = {};
var imgSeq = 0;
var _copiedVariant = null;

function uid(){ return Date.now().toString(36)+Math.random().toString(36).slice(2,5); }
function loginKey(e){ if(e.key==='Enter') doLogin(); }
function $(id){ return document.getElementById(id); }

// ── LOGIN ──
async function doLogin(){
  var u=($('login-user').value||'').trim();
  var p=($('login-pass').value||'').trim();
  var err=$('login-error');
  var btn=$('login-btn');
  if(!u||!p){err.textContent='الرجاء إدخال اسم المستخدم وكلمة المرور';return;}
  btn.textContent='جاري التحقق...'; btn.disabled=true; err.textContent='';
  try {
    var res=await fetch(PAGE_FEED_URL);
    if(!res.ok) throw new Error('تأكد أن صفحة الصلاحيات منشورة ومتاحة للعموم.');
    var json=await res.json();
    if(!json||!json.entry||!json.entry.content) throw new Error('صفحة الصلاحيات فارغة أو تنسيقها غير صحيح.');
    var raw=json.entry.content.$t.replace(/<[^>]+>/g,'\n');
    var lines=raw.split('\n');
    var found=null;
    for(var i=0;i<lines.length;i++){
      var parts=lines[i].split(':').map(function(s){return s.trim();}).filter(Boolean);
      if(parts.length<2) continue;
      if(parts[1]==='AD'&&parts.length>=3){
        // Admin: username:AD:password
        if(parts[0]===u&&parts[2]===p){found={name:parts[0],pass:p,isAdmin:true,section:'all'};break;}
      } else {
        // Rep: username:password[:section]
        if(parts[0]===u&&parts[1]===p){found={name:parts[0],pass:p,isAdmin:false,section:parts[2]||''};break;}
      }
    }
    if(found){
      currentUser=found;
      $('login-screen').classList.add('hidden');
      $('dashboard').classList.remove('hidden');
      $('user-badge').textContent=found.name+(found.isAdmin?' 👑':' 🏪');
      $('hdr-sub').textContent=found.isAdmin?'مدير — صلاحية جميع الأقسام':'قسمك: '+found.section;
      if(!found.isAdmin&&found.section){
        $('pcat').value=found.section;
        $('pcat').readOnly=true;
      }
      if(!vcCount) addV();
    } else {
      err.textContent='❌ اسم المستخدم أو كلمة المرور غير صحيحة.';
    }
  } catch(e){ err.textContent='❌ '+e.message; }
  finally { btn.textContent='تسجيل الدخول'; btn.disabled=false; }
}

function doLogout(){
  currentUser=null;
  $('dashboard').classList.add('hidden');
  $('login-screen').classList.remove('hidden');
  $('login-user').value=''; $('login-pass').value=''; $('login-error').textContent='';
}

// ── IMGBB ──
function toggleImgBB(){
  var b=$('setBody'),a=$('setArrow');
  var open=b.style.display==='none';
  b.style.display=open?'':'none';
  a.style.transform=open?'rotate(180deg)':'rotate(0)';
}
function getKey(){ return ($('imgbbKey').value||'').trim(); }
function saveKey(){
  try{localStorage.setItem('sb_imgbb_key',getKey());}catch(e){}
  updateUpStatus();
}
function updateUpStatus(){
  var s=$('upStatus');
  if(getKey()){s.textContent='مفعّل ✓';s.style.cssText='background:#dcfce7;color:#059669;font-size:11px;font-weight:800;padding:3px 10px;border-radius:20px;';}
  else{s.textContent='غير مفعّل';s.style.cssText='background:#dbeafe;color:#1d4ed8;font-size:11px;font-weight:800;padding:3px 10px;border-radius:20px;';}
}

// ── VARIANTS ──
function addV(){
  vcCount++; var i=vcCount; varImgs[i]=[];
  var d=document.createElement('div'); d.className='vc-wrap'; d.id='v'+i;
  d.innerHTML=
    '<div class="vc-header">'
    +'<div class="vc-title"><div class="num">'+i+'</div>اللون / الخيار #'+i+'</div>'
    +'<div class="vc-actions">'
    +'<button class="btn btn-ghost btn-icon" title="نسخ هذا الخيار" onclick="copyVariant('+i+')">📋 نسخ</button>'
    +'<button class="btn btn-ghost btn-icon" title="لصق خيار منسوخ" onclick="pasteVariant('+i+')">📥 لصق</button>'
    +(i>1?'<button class="btn btn-danger" onclick="rmV('+i+')">✕ حذف</button>':'')
    +'</div></div>'

    +'<div class="field"><label>اسم اللون / الخيار</label>'
    +'<input type="text" id="vc'+i+'-color" placeholder="مثال: أسود، أزرق سماوي، مقاس L..." /></div>'

    +'<div class="field"><label>الوصف</label>'
    +'<textarea id="vc'+i+'-desc" placeholder="اكتب وصفاً جذاباً للمنتج هنا..."></textarea></div>'

    +'<div class="field">'
    +'<label>الصور <span style="font-size:11px;font-weight:400;color:var(--txt3)">(روابط URL أو صور الجهاز مع ImgBB)</span></label>'
    +'<div class="img-zone" id="zone'+i+'" ondragover="dragOver(event,'+i+')" ondragleave="dragLeave('+i+')" ondrop="dropImg(event,'+i+')">'
    +'<div class="img-zone-body">'
    +'<div class="img-thumbs" id="thumbs'+i+'"></div>'
    +'<div class="img-drop-hint" id="hint'+i+'" onclick="pickFile('+i+')">'
    +'<svg width="32" height="32" fill="none" stroke="currentColor" stroke-width="1.5" viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="M8.5 10a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3z"/><path d="M21 15l-5-5L5 21"/></svg>'
    +'<span>اسحب صور هنا أو <b>اضغط للاختيار</b></span>'
    +'<span style="font-size:11px;color:var(--txt3);">PNG, JPG, WEBP</span>'
    +'</div>'
    +'</div>'
    +'<div class="img-url-bar">'
    +'<input type="url" id="urlInput'+i+'" placeholder="أو الصق رابط صورة https://..." onkeydown="urlKey(event,'+i+')" />'
    +'<button class="btn btn-primary btn-icon" onclick="addUrl('+i+')">＋ أضف</button>'
    +'</div>'
    +'<input type="file" id="file'+i+'" accept="image/*" multiple style="display:none;" onchange="filesChosen(event,'+i+')" />'
    +'</div></div>'

    +'<div class="field">'
    +'<label>الأحجام والأسعار <span style="font-size:11px;font-weight:400;color:var(--txt3)">(اترك الحجم فارغاً إن كان سعراً واحداً)</span></label>'
    +'<div id="vc'+i+'-sizes"></div>'
    +'<button class="btn btn-ghost" style="margin-top:6px;font-size:12.5px;" onclick="addSz('+i+')">＋ إضافة حجم / سعر</button>'
    +'</div>'

    +'<div class="grid2">'
    +'<div class="field"><label>السعر القديم <span class="badge-opt">للخصم</span></label>'
    +'<input type="number" id="vc'+i+'-oldp" placeholder="0" /></div>'
    +'<div class="field"><label>سطر إضافي <span class="badge-opt">اختياري</span></label>'
    +'<input type="text" id="vc'+i+'-extra" placeholder="مثال: شامل الضريبة، متوفر الآن..." /></div>'
    +'</div>';
  $('vc').appendChild(d);
  addSz(i);
}

function rmV(i){var e=$('v'+i);if(e){e.remove();delete varImgs[i];}}
function pickFile(i){$('file'+i).click();}

function addSz(i){
  var c=$('vc'+i+'-sizes');
  var rid='s'+uid();
  var r=document.createElement('div'); r.className='sr'; r.id=rid;
  r.innerHTML='<input type="text" placeholder="الحجم / المقاس (مثال: L، 256GB، كبير...)" />'
    +'<input type="number" placeholder="السعر ر.س" />'
    +'<button class="btn btn-danger" style="padding:6px 8px;" onclick="document.getElementById(\''+rid+'\').remove()">✕</button>';
  c.appendChild(r);
}

// ── VARIANT COPY / PASTE ──
function readVariantData(i){
  var szRows=[];
  var szBox=$('vc'+i+'-sizes');
  if(szBox) szBox.querySelectorAll('.sr').forEach(function(row){
    var ins=row.querySelectorAll('input');
    szRows.push({label:ins[0]?ins[0].value:'',price:ins[1]?ins[1].value:''});
  });
  return {
    color:($('vc'+i+'-color')||{value:''}).value,
    desc: ($('vc'+i+'-desc') ||{value:''}).value,
    oldp: ($('vc'+i+'-oldp') ||{value:''}).value,
    extra:($('vc'+i+'-extra')||{value:''}).value,
    sizes:szRows,
    imgs:(varImgs[i]||[]).map(function(x){return {src:x.src,status:x.status||'ready'};})
  };
}

function applyVariantData(i,v){
  if($('vc'+i+'-color')) $('vc'+i+'-color').value=v.color||'';
  if($('vc'+i+'-desc'))  $('vc'+i+'-desc').value =v.desc||'';
  if($('vc'+i+'-oldp'))  $('vc'+i+'-oldp').value =v.oldp||'';
  if($('vc'+i+'-extra')) $('vc'+i+'-extra').value=v.extra||'';
  var szBox=$('vc'+i+'-sizes');
  if(szBox){
    szBox.innerHTML='';
    (v.sizes||[]).forEach(function(sz){
      if(sz.price||sz.label){
        addSz(i);
        var rows=szBox.querySelectorAll('.sr');var last=rows[rows.length-1];
        if(last){var ins=last.querySelectorAll('input');if(ins[0])ins[0].value=sz.label||'';if(ins[1])ins[1].value=sz.price||'';}
      }
    });
    if(!v.sizes||!v.sizes.length) addSz(i);
  }
  varImgs[i]=[];
  (v.imgs||[]).forEach(function(im){if(im.src&&/^https?:\/\//.test(im.src))varImgs[i].push({id:++imgSeq,src:im.src,status:'ready'});});
  renderThumbs(i);
}

function copyVariant(i){
  _copiedVariant=readVariantData(i);
  var json=JSON.stringify(_copiedVariant);
  var done=function(ok){showToast(ok?'📋 تم نسخ الخيار — اضغط 📥 للصق':'📋 تم حفظ الخيار','#2563eb');};
  if(navigator.clipboard&&navigator.clipboard.writeText)
    navigator.clipboard.writeText(json).then(function(){done(true);},function(){done(false);});
  else done(false);
}

function pasteVariant(i){
  var apply=function(text){
    var v=null;
    try{var p=JSON.parse(text);if(p&&typeof p.color!=='undefined')v=p;}catch(e){}
    if(v){applyVariantData(i,v);showToast('✅ تم لصق الخيار','#059669');}
    else if(_copiedVariant){applyVariantData(i,_copiedVariant);showToast('✅ تم لصق الخيار','#059669');}
    else showToast('⚠️ لا يوجد خيار منسوخ — اضغط 📋 أولاً','#dc2626');
  };
  if(navigator.clipboard&&navigator.clipboard.readText)
    navigator.clipboard.readText().then(apply,function(){
      if(_copiedVariant){applyVariantData(i,_copiedVariant);showToast('✅ تم لصق الخيار','#059669');}
      else showToast('⚠️ لا يوجد خيار منسوخ','#dc2626');
    });
  else{
    if(_copiedVariant){applyVariantData(i,_copiedVariant);showToast('✅ تم لصق الخيار','#059669');}
    else showToast('⚠️ لا يوجد خيار منسوخ','#dc2626');
  }
}

// ── IMAGES ──
function dragOver(e,i){e.preventDefault();$('zone'+i).classList.add('drag-over');}
function dragLeave(i){$('zone'+i).classList.remove('drag-over');}
function dropImg(e,i){
  e.preventDefault();dragLeave(i);
  var url=e.dataTransfer.getData('text/uri-list')||e.dataTransfer.getData('text/plain')||'';
  if(url&&/^https?:\/\//i.test(url.trim())){
    url.trim().split(/\s+/).forEach(function(u){if(/^https?:\/\//i.test(u))addUrlImg(i,u);}); return;
  }
  if(e.dataTransfer.files&&e.dataTransfer.files.length) readFiles(i,e.dataTransfer.files);
}
function filesChosen(e,i){readFiles(i,e.target.files);e.target.value='';}
function readFiles(i,files){Array.from(files).forEach(function(f){if(f.type.startsWith('image/'))handleFile(i,f);});}
function urlKey(e,i){if(e.key==='Enter'){e.preventDefault();addUrl(i);}}
function addUrl(i){
  var inp=$('urlInput'+i);
  var val=(inp.value||'').trim();if(!val)return;
  val.split(/[\n,]+/).forEach(function(u){u=u.trim();if(u&&/^https?:\/\//i.test(u))addUrlImg(i,u);});
  inp.value='';
}
function addUrlImg(i,url){
  if(!varImgs[i])varImgs[i]=[];
  if(varImgs[i].some(function(x){return x.src===url;}))return;
  varImgs[i].push({id:++imgSeq,src:url,status:'ready'});
  renderThumbs(i);
}
function handleFile(i,file){
  if(!varImgs[i])varImgs[i]=[];
  var reader=new FileReader();
  reader.onload=function(ev){
    var b64=ev.target.result;
    var entry={id:++imgSeq,src:b64,status:getKey()?'uploading':'error',err:getKey()?'':'أضف مفتاح ImgBB أعلاه'};
    varImgs[i].push(entry);renderThumbs(i);
    if(getKey()) uploadToImgBB(i,entry,b64);
  };
  reader.readAsDataURL(file);
}
function uploadToImgBB(i,entry,b64){
  var pure=b64.indexOf(',')>=0?b64.split(',')[1]:b64;
  var fd=new FormData();fd.append('key',getKey());fd.append('image',pure);
  fetch('https://api.imgbb.com/1/upload',{method:'POST',body:fd})
    .then(function(r){return r.json();})
    .then(function(j){
      if(j&&j.success&&j.data&&(j.data.display_url||j.data.url)){
        entry.src=j.data.display_url||j.data.url;entry.status='ready';entry.err='';
      } else {entry.status='error';entry.err=(j&&j.error&&j.error.message)||'فشل الرفع';}
      renderThumbsAll();
    }).catch(function(){entry.status='error';entry.err='تعذّر الاتصال';renderThumbsAll();});
}
function removeImgById(i,id){if(varImgs[i])varImgs[i]=varImgs[i].filter(function(x){return x.id!==id;});renderThumbs(i);}
function renderThumbsAll(){Object.keys(varImgs).forEach(function(k){renderThumbs(k);});}
function renderThumbs(i){
  var box=$('thumbs'+i);if(!box)return;
  var hint=$('hint'+i);
  var imgs=varImgs[i]||[];
  if(hint) hint.style.display=imgs.length?'none':'';
  box.innerHTML=imgs.map(function(img){
    var ov='';
    if(img.status==='uploading') ov='<div class="overlay" style="background:rgba(15,23,42,.6);">⏳</div>';
    else if(img.status==='error') ov='<div class="overlay" title="'+(img.err||'')+'" style="background:rgba(220,38,38,.7);">⚠️</div>';
    return '<div class="img-thumb"><img src="'+img.src+'" />'+ov+'<button class="rm" onclick="removeImgById('+i+','+img.id+')">✕</button></div>';
  }).join('');
}
document.addEventListener('paste',function(e){
  var items=e.clipboardData&&e.clipboardData.items;if(!items)return;
  var zi=window._focusedV||1;var hadImg=false;
  Array.from(items).forEach(function(item){if(item.type.startsWith('image/')){hadImg=true;var f=item.getAsFile();if(f)handleFile(zi,f);}});
  if(!hadImg){
    var text=e.clipboardData.getData('text')||'';
    if(text&&/^https?:\/\//i.test(text.trim())){
      var active=document.activeElement;
      if(!active||active.type!=='url'){e.preventDefault();text.trim().split(/[\n,]+/).forEach(function(u){u=u.trim();if(/^https?:\/\//i.test(u))addUrlImg(zi,u);});}
    }
  }
});
document.addEventListener('focusin',function(e){
  var vc=e.target.closest('.vc-wrap');
  if(vc){var m=vc.id.match(/^v(\d+)$/);if(m)window._focusedV=parseInt(m[1]);}
});

// ── BUILD POST HTML ──
function buildPostHTML(){
  var title=($('ptitle').value||'').trim();
  if(!title){alert('يرجى كتابة عنوان المنتج أولاً');return null;}
  var rating=($('prating').value||'').trim();
  var ratcount=($('pratcount').value||'').trim();
  var globalLines=[];
  if(rating)   globalLines.push('التقييم: '+rating);
  if(ratcount) globalLines.push('عدد التقييمات: '+ratcount);
  var skippedBase64=0,stillUploading=0;
  var sections=[];
  document.querySelectorAll('.vc-wrap').forEach(function(card){
    var i=parseInt(card.id.replace('v',''));
    var color=($('vc'+i+'-color')||{value:''}).value.trim();
    var desc =($('vc'+i+'-desc') ||{value:''}).value.trim();
    var oldp =($('vc'+i+'-oldp') ||{value:''}).value.trim();
    var extra=($('vc'+i+'-extra')||{value:''}).value.trim();
    var szLabels=[],szPrices=[];
    card.querySelectorAll('.sr').forEach(function(row){
      var ins=row.querySelectorAll('input');
      var lbl=ins[0]?ins[0].value.trim():'';
      var prc=ins[1]?ins[1].value.trim():'';
      if(prc){szLabels.push(lbl);szPrices.push(prc);}
    });
    var imgs=(varImgs[i]||[]).filter(function(img){
      if(img.status==='uploading'){stillUploading++;return false;}
      if(img.status!=='ready'||!/^https?:\/\//i.test(img.src)){skippedBase64++;return false;}
      return true;
    });
    var lines=[];
    if(color) lines.push('اللون: '+color);
    if(desc){lines.push('الوصف:');lines.push(desc);}
    if(oldp) lines.push('السعر القديم: '+oldp);
    if(extra) lines.push(extra);
    var hasSzLbls=szLabels.some(function(l){return !!l;});
    if(szPrices.length===1&&!hasSzLbls){
      lines.push('السعر: '+szPrices[0]);
    } else if(szPrices.length>0){
      lines.push('السعر:');szPrices.forEach(function(p){lines.push(p);});
      if(hasSzLbls){lines.push('الحجم:');szLabels.forEach(function(l,k){lines.push(l||('خيار '+(k+1)));});}
    }
    var html=lines.map(function(l){return '<div>'+esc(l)+'</div>';}).join('\n');
    imgs.forEach(function(img){html+='\n<div>'+img.src+'</div>';});
    if(html.trim()) sections.push(html);
  });
  if(!sections.length){alert('يرجى إدخال بيانات على الأقل للخيار الأول');return null;}
  var prefix=globalLines.map(function(l){return '<div>'+esc(l)+'</div>';}).join('\n');
  if(prefix) sections[0]=prefix+'\n'+sections[0];
  return {html:sections.join('\n<div>·····</div>\n'),skippedBase64:skippedBase64,stillUploading:stillUploading};
}

function genCode(){
  var result=buildPostHTML();if(!result)return;
  $('out').value=result.html;
  $('out-wrap').classList.remove('hidden');
  showWarn(result);
  doCopy(function(ok){
    var b=$('cbtn');
    if(b){b.textContent=ok?'✅ تم النسخ!':'نسخ الكود';setTimeout(function(){b.textContent='نسخ الكود';},2500);}
    showToast(ok?'✅ تم نسخ الكود — افتح Blogger واضغط HTML ثم الصق':'⚠️ اضغط «نسخ الكود» يدوياً',ok?'#059669':'#dc2626');
  });
  setTimeout(function(){$('out-wrap').scrollIntoView({behavior:'smooth',block:'start'});},120);
}

function showWarn(result){
  var warn=$('b64warn');
  if(result.stillUploading>0){
    warn.className='warn-uploading';
    warn.innerHTML='⏳ ما زال '+result.stillUploading+' صورة قيد الرفع — انتظر ثوانٍ ثم اضغط مرة أخرى.';
  } else if(result.skippedBase64>0){
    warn.className='warn-base64';
    warn.innerHTML='⚠️ تم تخطي '+result.skippedBase64+' صورة من الجهاز — فعّل الرفع الذكي (ImgBB) أعلى الصفحة.';
  } else {warn.className='';warn.innerHTML='';}
}

// ── DIRECT PUBLISH ──
async function publishDirectly(){
  if(!currentUser){showToast('⚠️ يجب تسجيل الدخول أولاً','#dc2626');return;}
  var result=buildPostHTML();if(!result)return;
  if(result.stillUploading>0){showToast('⏳ انتظر اكتمال رفع الصور أولاً','#d97706');return;}
  var title=($('ptitle').value||'').trim();
  var cat=($('pcat').value||'').trim();
  if(!cat){showToast('⚠️ يرجى تحديد التصنيف / القسم','#dc2626');return;}
  var btn=$('pub-btn');
  var statusDiv=$('pub-status');
  btn.disabled=true; btn.textContent='جاري النشر...';
  statusDiv.innerHTML='<div class="status-box status-loading">🚀 جاري الإرسال إلى المتجر...</div>';
  try {
    var res=await fetch(APPS_SCRIPT_URL,{
      method:'POST',
      body:JSON.stringify({
        action:'publishPost',
        username:currentUser.name,
        password:currentUser.pass,
        title:title,
        content:result.html,
        labels:[cat]
      })
    });
    var data=await res.json();
    if(data&&data.success){
      statusDiv.innerHTML='<div class="status-box status-success">✅ تم نشر المنتج بنجاح! يظهر الآن في المتجر.</div>';
      $('out-wrap').classList.add('hidden');
      setTimeout(function(){
        $('ptitle').value='';
        if(currentUser.isAdmin) $('pcat').value='';
        $('prating').value=''; $('pratcount').value='';
        $('vc').innerHTML=''; vcCount=0; varImgs={}; addV();
        statusDiv.innerHTML='';
        showToast('✅ الفورم جاهز لمنتج جديد','#059669');
      },4000);
    } else {
      statusDiv.innerHTML='<div class="status-box status-error">❌ '+(data&&data.message?data.message:'فشل النشر — تحقق من إعدادات Apps Script')+'</div>';
    }
  } catch(e){
    statusDiv.innerHTML='<div class="status-box status-error">❌ خطأ في الاتصال: '+e.message+'</div>';
  } finally {
    btn.disabled=false; btn.textContent='🚀 إنشاء ونشر مباشرة في المتجر';
  }
}

// ── SETTINGS ──
function readAllSettings(){
  var data={v:'1',title:$('ptitle').value||'',cat:$('pcat').value||'',rating:$('prating').value||'',ratcount:$('pratcount').value||'',variants:[]};
  document.querySelectorAll('.vc-wrap').forEach(function(card){
    var i=parseInt(card.id.replace('v',''));
    var szRows=[];
    card.querySelectorAll('.sr').forEach(function(row){
      var ins=row.querySelectorAll('input');
      szRows.push({label:ins[0]?ins[0].value:'',price:ins[1]?ins[1].value:''});
    });
    data.variants.push({
      color:($('vc'+i+'-color')||{value:''}).value,
      desc: ($('vc'+i+'-desc') ||{value:''}).value,
      oldp: ($('vc'+i+'-oldp') ||{value:''}).value,
      extra:($('vc'+i+'-extra')||{value:''}).value,
      sizes:szRows,
      imgs:(varImgs[i]||[]).map(function(x){return {src:x.src,status:x.status||'ready'};})
    });
  });
  return data;
}

function copySettings(){
  var json=JSON.stringify(readAllSettings(),null,2);
  var done=function(ok){showToast(ok?'✅ تم نسخ الإعدادات':'⚠️ فشل النسخ',ok?'#059669':'#dc2626');};
  if(navigator.clipboard&&navigator.clipboard.writeText)
    navigator.clipboard.writeText(json).then(function(){done(true);},function(){done(legacyCopyText(json));});
  else done(legacyCopyText(json));
}

function pasteSettings(){
  if(navigator.clipboard&&navigator.clipboard.readText)
    navigator.clipboard.readText().then(function(t){applyPasted(t);},function(){promptPaste();});
  else promptPaste();
}

function promptPaste(){
  var t=prompt('الصق هنا: إعدادات منسوخة أو كود منشور Blogger:');
  if(t) applyPasted(t);
}

function applyPasted(text){
  if(!text||!text.trim()){showToast('⚠️ لم يتم لصق أي شيء','#dc2626');return;}
  var t=text.trim();
  if(t.charAt(0)==='{'){
    var data;try{data=JSON.parse(t);}catch(e){showToast('⚠️ البيانات غير صالحة','#dc2626');return;}
    if(!data||!data.variants){showToast('⚠️ لم يُعثر على بيانات','#dc2626');return;}
    applyData(data);showToast('✅ تم استعادة الإعدادات بنجاح','#059669');
  } else {
    var parsed=importFromCode(t);
    if(!parsed.variants.length){showToast('⚠️ لم أتمكن من قراءة الكود','#dc2626');return;}
    applyData(parsed);showToast('✅ تم استيراد المنتج — عدّل ما تريد ثم أعد التوليد','#059669');
  }
}

function importFromCode(raw){
  var data={title:'',cat:'',rating:'',ratcount:'',variants:[]};
  var toEn=function(s){return String(s).replace(/[٠-٩]/g,function(w){return '٠١٢٣٤٥٦٧٨٩'.indexOf(w);});};
  var sections=raw.replace(/&nbsp;|&#160;/gi,' ').split(/(?:<[^>]*>\s*)*[·.•‧⋅]{5,}(?:\s*<[^>]*>)*/);
  sections.forEach(function(sec){
    var urls=[],re=/(?:src|href)\s*=\s*["']([^"']+)["']/gi,mm;
    while((mm=re.exec(sec))){if(/^https?:\/\//i.test(mm[1]))urls.push(mm[1].replace(/&amp;/g,'&'));}
    var text=sec.replace(/<br\s*\/?>/gi,'\n').replace(/<\/(p|div|h[1-6])>/gi,'\n').replace(/<[^>]+>/g,'');
    var lines=text.split('\n').map(function(l){return l.trim();}).filter(function(l){return l&&!/^[·.•‧⋅]{3,}$/.test(l);});
    lines.forEach(function(l){if(/^https?:\/\/\S+$/i.test(l))urls.push(l.replace(/&amp;/g,'&'));});
    urls=urls.filter(function(u,k){return urls.indexOf(u)===k;});
    var v={color:'',desc:'',oldp:'',extra:'',sizes:[],imgs:urls.map(function(u){return {src:u,status:'ready'};})};
    var pp=[],ps=[],mode=null,hasData=false;
    lines.forEach(function(rawLine){
      var line=toEn(rawLine).replace(/：/g,':').trim();
      if(!line||/^https?:\/\//i.test(line)) return;
      var priceM=line.match(/^([0-9][0-9,.]*)\s*$/);
      if(mode==='prices'){if(priceM){pp.push(line.replace(/[,]/g,''));hasData=true;return;}mode=null;}
      if(mode==='sizes'){if(!priceM&&line.length<=50&&!/^(?:اللون|الوصف|السعر|الحجم|التقييم|عدد)/.test(line)){ps.push(line);return;}mode=null;}
      if(mode==='desc'){if(!/^(?:اللون|السعر|الحجم|السعر القديم|التقييم|عدد)/i.test(line)){v.desc=(v.desc?v.desc+' ':'')+line;return;}mode=null;}
      var rm=line.match(/^التقييم\s*[:\-]?\s*([0-9][0-9.]*)/i);if(rm){data.rating=rm[1];hasData=true;return;}
      var cm=line.match(/^عدد التقييمات\s*[:\-]?\s*([0-9]+)/i);if(cm){data.ratcount=cm[1];hasData=true;return;}
      if(/^السعر\s*[:\-]?\s*$/i.test(line)){mode='prices';return;}
      if(/^(?:الحجم|الأحجام|المقاس)\s*[:\-]?\s*$/i.test(line)){mode='sizes';return;}
      var dm=line.match(/^الوصف\s*[:\-]?\s*(.*)$/i);if(dm){if(dm[1]&&dm[1].trim()){v.desc=(v.desc?v.desc+' ':'')+dm[1].trim();}else{mode='desc';}hasData=true;return;}
      var om=line.match(/^السعر القديم\s*[:\-]?\s*([0-9][0-9.,]*)/i);if(om){v.oldp=om[1].replace(/[,]/g,'');hasData=true;return;}
      var pm=line.match(/^السعر\s*[:\-]\s*([0-9][0-9.,]*)/i);if(pm){v.sizes.push({label:'',price:pm[1].replace(/[,]/g,'')});hasData=true;return;}
      var clm=line.match(/^اللون\s*[:\-]?\s*(.+)/i);if(clm&&clm[1].trim()){v.color=clm[1].trim();hasData=true;return;}
      var hzm=line.match(/^(?:الحجم|المقاس)\s*[:\-]\s*(.+)/i);if(hzm&&hzm[1].trim()){v.sizes.push({label:hzm[1].trim(),price:''});hasData=true;return;}
      var szm=line.match(/^([^\s=:،,؛]+)\s*[=:]\s*([0-9][0-9.,]*)\s*$/);if(szm){v.sizes.push({label:szm[1].trim(),price:szm[2].replace(/[,]/g,'')});hasData=true;return;}
      v.desc=(v.desc?v.desc+' ':'')+rawLine.trim();hasData=true;
    });
    if(pp.length){var n=Math.max(pp.length,ps.length);for(var k=0;k<n;k++){v.sizes.push({label:ps[k]||'',price:pp[k]||''});}hasData=true;}
    else if(ps.length){ps.forEach(function(s){v.sizes.push({label:s,price:''});});hasData=true;}
    if(hasData||v.imgs.length) data.variants.push(v);
  });
  return data;
}

function applyData(data){
  $('ptitle').value=data.title||'';
  if(!currentUser||currentUser.isAdmin) $('pcat').value=data.cat||'';
  $('prating').value=data.rating||'';
  $('pratcount').value=data.ratcount||'';
  $('vc').innerHTML='';vcCount=0;varImgs={};
  (data.variants||[]).forEach(function(v){
    addV();var i=vcCount;
    if($('vc'+i+'-color')) $('vc'+i+'-color').value=v.color||'';
    if($('vc'+i+'-desc'))  $('vc'+i+'-desc').value =v.desc||'';
    if($('vc'+i+'-oldp'))  $('vc'+i+'-oldp').value =v.oldp||'';
    if($('vc'+i+'-extra')) $('vc'+i+'-extra').value=v.extra||'';
    var szBox=$('vc'+i+'-sizes');if(szBox)szBox.innerHTML='';
    (v.sizes||[]).forEach(function(sz){
      if(sz.price||sz.label){
        addSz(i);
        var rows=document.getElementById('vc'+i+'-sizes').querySelectorAll('.sr');
        var last=rows[rows.length-1];
        if(last){var ins=last.querySelectorAll('input');if(ins[0])ins[0].value=sz.label||'';if(ins[1])ins[1].value=sz.price||'';}
      }
    });
    if(!v.sizes||!v.sizes.length) addSz(i);
    varImgs[i]=[];
    (v.imgs||[]).forEach(function(im){if(im.src&&/^https?:\/\//.test(im.src))varImgs[i].push({id:++imgSeq,src:im.src,status:'ready'});});
    renderThumbs(i);
  });
}

// ── UTILS ──
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

function showToast(msg,color){
  var t=$('_toast');
  t.textContent=msg; t.style.background=color;
  requestAnimationFrame(function(){t.style.opacity='1';});
  clearTimeout(window._tt);
  window._tt=setTimeout(function(){t.style.opacity='0';},3800);
}

function doCopy(cb){
  var ta=$('out'),text=ta.value;
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(function(){cb&&cb(true);},function(){cb&&cb(legacyCopy(ta));});return;
  }
  cb&&cb(legacyCopy(ta));
}
function legacyCopy(ta){try{ta.focus();ta.select();ta.setSelectionRange(0,ta.value.length);var ok=document.execCommand('copy');window.getSelection&&window.getSelection().removeAllRanges();return !!ok;}catch(e){return false;}}
function legacyCopyText(text){try{var ta=document.createElement('textarea');ta.value=text;ta.style.cssText='position:fixed;opacity:0;';document.body.appendChild(ta);ta.select();var ok=document.execCommand('copy');document.body.removeChild(ta);return ok;}catch(e){return false;}}
function copyOut(){
  doCopy(function(ok){
    var b=$('cbtn');b.textContent=ok?'✅ تم!':'انسخ يدوياً';
    setTimeout(function(){b.textContent='نسخ الكود';},2500);
    showToast(ok?'✅ تم النسخ!':'⚠️ انسخ يدوياً',ok?'#059669':'#dc2626');
  });
}

